from common import *

def video(name,title,caption):return f'<figure><video controls playsinline preload="none" poster="assets/{name}-poster.jpg" style="width:100%;display:block" aria-label="{title}"><source src="assets/{name}.mp4" type="video/mp4">動画を再生できません。</video><figcaption>{caption}</figcaption></figure>'
def build():
 body=sec('seeing','見る研究：領域、奥行き、動き、視点',p('ここからは、実際の研究がどんな出力を生むかを見ます。著者が公開した結果には出典と条件を添え、教材用の図とは分けてあります。外部デモを開かなくても、手元の図や映像から仕組みと見どころを追えます。')+sub('<span id="sam2">SAM 2｜指定した対象を、動画の中で追う</span>',img('sam2-result.jpg','SAM 2の著者が公開したSA-Vデータセットの動画フレームと物体マスクの例','著者実装のSA-Vデータセット紹介図。色は対象のマスク。データセットの例示であり、この図全体をモデルの予測精度の証拠とは扱わない。')+p('SAM 2は指定した対象の領域を画像・動画で扱い、過去のフレームの情報を使います。見どころは、対象の形が変わる・一部が隠れる場面で、同じ対象の領域を保てるかです。入力の点や枠という指定、画像の特徴、時間をまたぐ記憶がつながります。')+p(ref('https://github.com/facebookresearch/sam2','SAM 2：著者実装・結果')+' · '+ref('https://sam2.metademolab.com/','外部の操作デモ')+' · <a href="spatial.html#video">動画の対応付けへ</a>'))+sub('<span id="depth-v2">Depth Anything V2｜一枚の画像を奥行きへ</span>',dual(img('depth-input.jpg','Depth Anything V2著者ページの入力写真','入力写真'),img('depth-result.jpg','同じ写真から推定したDepth Anything V2の深度マップ','著者公開のV2出力'),'著者ページのdetail comparisonから同一例を抜粋。カラーマップによって相対的な奥行きを表示。')+p('境界の細さや、近い物体と遠い背景の分かれ方を見ます。画像内の順序がもっともらしくても、メートル単位で正しいとは限りません。この研究は学習データと教師モデル・擬似ラベルの作り方にも工夫があります。')+p(ref('https://depth-anything-v2.github.io/','Depth Anything V2：結果と説明')+' · <a href="vision.html">深度推定のタスクへ</a>'))+sub('<span id="mediapipe">MediaPipe Pose｜動きを関節点の列へ</span>',img('pose-result.png','MediaPipe Poseの公式出力例。人体の関節点と接続を重ねた画像','MediaPipe Pose Landmarker公式ガイドの出力例を引用。カメラ入力やモデル実行は不要。')+p('姿勢推定では関節の座標を出します。フォームの研究では、その座標から角度や時刻ごとの変化を読みます。隠れた関節の推定、左右の取り違え、点の揺れを観察します。')+p(ref('https://ai.google.dev/edge/mediapipe/solutions/vision/pose_landmarker','MediaPipe Pose：公式の結果例とガイド')))+sub('NeRF｜撮影していない視点を描く',video('nerf-result','NeRFの著者公開の新規視点合成動画','Mildenhall et al.（2020）の著者公開結果 colorspout_200k_rgb。視点を動かしたときの見え方を確認する。')+p('複数の撮影画像から場面の色と密度を表す関数を学び、新しい視線に沿って色を積分して描画します。奥行きに応じた見え方、遮蔽、反射の変化を見ます。生成画像の自然さと、正確な3D表面の復元は別に評価します。')+p(ref('https://www.matthewtancik.com/nerf','NeRF：著者ページ')+' · <a href="spatial.html#space">3Dの表現へ</a>')))
 body+=sec('signals','系列を扱う研究：予測、異常、音',sub('TimesFM｜多様な系列で事前学習する',img('timesfm-result.png','TimesFM原論文Figure 4のDartsとMonashの系列の予測例','Das et al.（ICML 2024）, Figure 4を引用。下段は将来の予測区間の拡大。青の正解系列と橙のTimesFM予測が、どこで一致し外れるかを見る。')+p('2024年のTimesFMは、時系列のパッチを扱うdecoder-only Transformerを多様な系列で事前学習する研究です。目的ごとにゼロから学ぶ場合と比べ、既に得た時系列の知識を新しい系列へ使えるかを問います。図の縦の境界より右は入力に混ぜず、将来の正解と予測を比べます。')+p(ref('https://arxiv.org/abs/2310.10688','TimesFM：2024年の原論文')+' · '+ref('https://github.com/google-research/timesfm','著者実装（複数の版あり）')))+sub('Merlion｜異常スコアと評価をつなぐ',img('merlion-result.png','Merlion著者実装の異常検知の出力例','Merlion公式READMEの異常検知図を引用。黒は観測値（左軸）、赤い線は異常スコア（右軸）、赤い帯は異常区間。両軸の尺度が違うことに注意。')+p('Merlionは単一のニューラルネットワーク名ではなく、時系列の異常検知・予測などを扱うフレームワークです。検出した区間が実際の異常と重なるか、遅れや誤警報がないかを見ます。前処理・閾値・評価の統一も研究や検証を支える仕事です。')+p(ref('https://github.com/salesforce/Merlion','Merlion：著者実装とチュートリアル')))+sub('Demucs｜混合音から音源を取り出す',flow([('混合音','声＋複数の楽器',BLUE),('分離モデル','時間・周波数の構造'),('音源ごとの波形','ボーカル・伴奏など',ORANGE)],'音源分離の目標。下の音は周波数成分を合成した教材例で、Demucsの結果ではない。')+'<div class="compare"><div><p>混合した合成音</p><audio controls preload="none" src="assets/mix.wav"></audio></div><div><p>元の低い成分</p><audio controls preload="none" src="assets/low.wav"></audio></div></div>'+p('Demucsの研究では、波形とスペクトログラムを組み合わせるなどして、楽曲の音源を分離します。著者の試聴結果では、他音源の漏れと、分離した音の歪みに耳を向けます。公開実装はアーカイブ済みなので、実行を教材の前提にはしません。')+p(ref('https://github.com/facebookresearch/demucs','Demucs：著者実装・試聴先へのリンク')+' · <a href="audio.html#listen">音の表現へ</a>')))
 body+=sec('language-action','言葉と行動の研究：探す、答える、動かす',sub('RAG｜文書を探してから答える',flow([('質問','見学会の受付は？',BLUE),('文書を検索','「受付9:30」の文書'),('文書を条件に生成','質問と根拠を使う'),('回答','9時30分です',ORANGE)],'教材用の入出力例。検索結果の取り違えと、生成時の誤りを切り分けられる。')+p('検索でどの根拠を取得したか、回答がその根拠を正しく使うかを別々に評価します。モデルを変える研究だけでなく、文書の区切り方、検索、根拠の提示にも研究上の問いがあります。')+p(ref('https://arxiv.org/abs/2005.11401','Retrieval-Augmented Generation 原論文')+' · <a href="language.html#rag">検索と生成の接続へ</a>'))+sub('RT-2｜視覚と言語の知識を、ロボットの行動へ',video('rt2-result','RT-2の著者公開ロボット操作動画','RT-2（2023）著者ページのrt2_teaser映像。入力の指示と、対象を選んで動かす行動の対応を見る。')+p('画像と言語を扱うモデルから行動トークンを出すように学習し、ロボットの操作へ接続する研究です。どの物体を選ぶかという意味の理解と、実際に動かす制御の両方が関係します。映像は成功例の提示なので、性能全体は論文の評価条件と合わせて判断します。')+p(ref('https://robotics-transformer2.github.io/','RT-2：著者ページ')+' · <a href="language.html#vlm">VLMの構造へ</a>'))+sub('AlphaGo｜方策、価値、探索の組み合わせ',flow([('盤面','次の手を考える',BLUE),('方策','有望な候補を選ぶ'),('探索＋価値','先の展開を評価'),('着手','選んだ手を実行',ORANGE)],'AlphaGoの役割分担の模式図。原論文では人の棋譜を使う学習、強化学習、探索を組み合わせる。')+p('すべての手を同じ深さで調べる代わりに、学んだ方策で候補を絞り、価値関数などを使って先を評価します。学ぶ部分と、利用時に探索する部分の組み合わせが見どころです。')+p(ref('https://www.nature.com/articles/nature16961','AlphaGo 原論文'))))
 body+=sec('design-control','設計と制御の研究：実世界の制約へ',sub('データセンターの冷却｜センサから設定を選ぶ',flow([('温度・設備の状態','センサ観測',BLUE),('設定候補を評価','制約の中で選ぶ'),('冷却設備を制御','次の状態を観測'),('結果を評価','エネルギーと制約',ORANGE)],'DeepMindの公式事例を基にした役割の模式図。ゲームの得点と違い、設備の制約を満たしながら効率を考える。')+p('見どころは、予測が良いだけでなく、選んだ設定を設備で使えるかです。監視、制約、失敗時の対応を含めたシステムとして評価します。')+p(ref('https://deepmind.google/blog/safety-first-ai-for-autonomous-data-centre-cooling-and-industrial-control/','冷却制御：公式事例')))+sub('配送経路｜都市の集合から訪問順序へ',img('kool2019-tsp-decoder.png','4段階で都市3、1、2、4を選ぶTSPのデコーダ','Koolら（ICLR 2019）の<a href="https://arxiv.org/pdf/1803.08475#page=4">Figure 2, p.4</a>を引用。図領域を切り出し。選択手順の説明図。<a href="decision-science.html#learn-routing">図の詳しい読み方とスケジューリングの例へ</a>')+p('Attention, Learn to Solve Routing Problems!は、都市の特徴と訪問済みの状態から次の都市を選ぶ方策を学ぶ研究です。REINFORCEという方策勾配法で経路の長さを学習信号にします。解が短いかだけでなく、制約を守るか、既存ソルバとの時間・品質の比較、都市数の違いへ使えるかを調べます。')+p(ref('https://github.com/wouterkool/attention-learn-to-route','著者実装と原論文')))+sub('AlphaFold｜配列から構造を予測する',img('protein.svg','AlphaFold DBのP69905のCα予測座標とpLDDTの色分け','AlphaFold DB：AF-P69905-F1-model_v6。ヒトのヘモグロビンαサブユニット、142残基の予測。座標と信頼度を使って教材側で描画したもので、実験で測定された構造ではない。')+'<div class="demo" data-demo="protein"><strong>予測構造を回転して見る</strong><label>横方向の回転 <input type="range" min="0" max="360" value="0"></label><div class="protein-plot"></div><p class="result">色はpLDDT。濃青：90以上、水色：70–90、黄：50–70、橙：50未満。座標の回転だけを行い、予測を再計算しません。</p></div>'+flow([('アミノ酸配列など','利用する情報は版で異なる',BLUE),('構造を推定するモデル','残基の関係と幾何'),('3D座標＋信頼度','領域ごとに確認',ORANGE)],'構造予測の入出力。AlphaFold DBは既存の予測構造を閲覧する場所で、その場で新規配列を予測するサービスとは異なる。')+p('構造の色分けで示すpLDDTは局所的な構造への信頼度の指標です。低い領域は、柔軟性や予測の難しさなど複数の理由で生じます。高い局所信頼度だけで、領域間の配置や実際の機能まで確定できるわけではありません。')+p(ref('https://alphafold.ebi.ac.uk/','AlphaFold DB：構造を回転して閲覧')+' · <a href="science.html#science">科学応用へ</a>')))
 body+=sec('connections','一つの実問題にも、違う研究の問いがある',table(['実問題','タスク・データ・モデル','学び方・研究上の問い'],[('工場の外観検査','画像分類・異常検知 / 製品画像 / CNN・ViT','転移・少数ラベル / 撮影条件への頑健性、欠陥に注目したかを調べるXAI、端末上の推論'),('文書に答えるAI','検索・回答生成 / 文書と質問 / Transformer LLM','事前学習・指示への適応 / 根拠の忠実さ、未知の質問への不確実性、長文の計算量'),('物を運ぶロボット','認識・行動選択 / 画像・センサ・指示 / VLM・方策モデル','模倣・強化学習など / 環境差への頑健性、長期計画、実行時間の制約')])+p('AI研究は、大きなモデルを作ることだけではありません。どんな情報で学ぶか、何に失敗するか、判断をどう説明するか、どの制約で動かすかを明らかにすることも研究です。')+p('本編06はここまでです。モデル構造やXAIを再確認したいときは左の目次へ。古典手法は任意の<a href="classics.html">補足ページ</a>にまとめています。05で得た128次元の表現の可視化を扱うA01は、本章とは別のおまけ教材として準備中です。'))
 page('research','具体的な研究 — 何ができるようになるのか','研究例と補足','05 / RESEARCH IN PRACTICE','画像から空間へ、音から構造へ、言葉から行動へ。公開された結果と具体的な入出力から、研究の工夫を見ます。',body)
 b=box(260,25,240,60,'ある特徴 ≤ 閾値？')+box(90,150,200,60,'予測 A','条件を満たす',BLUE)+box(480,150,200,60,'予測 B','条件を満たさない',ORANGE)+line(295,91,197,144)+line(464,91,578,144)+txt(200,110,'はい',13)+txt(570,110,'いいえ',13)
 body=sec('prediction','予測する古典手法',p('深層学習の研究を読むための必須前提ではありませんが、比較の基準や小規模なデータの方法として知っておくと関係が見えます。線形回帰とロジスティック回帰は02・03で扱いました。')+table(['手法','発想','見ておく違い'],[('線形回帰・ロジスティック回帰','特徴の重み付き和から予測','特徴をどう作るかで表現力が変わる'),('決定木','条件で分岐を繰り返す','小さな木はルールを追える。深い木は複雑になる'),('ランダムフォレスト','データや特徴を変えた複数の木をまとめる','木の予測を平均・投票する'),('勾配ブースティング','損失を改善するモデルを逐次追加','前の不足を補うよう組み合わせる'),('SVM','境界とデータの間の余裕を重視','カーネルで非線形な境界も扱う')])+figure(svg(b,245,label='小さな決定木の条件分岐'),'決定木の一回の分岐。どの特徴と閾値で分けるかをデータから選ぶ。'))
 body+=sec('structure','構造を探す古典手法',table(['手法','何を作る？','注意点'],[('k-means','指定したk個の中心と、近い中心への割り当て','kを決める必要。距離・特徴の尺度・クラスタの形が結果に影響'),('PCA','分散が大きい方向への線形な座標','分類に重要な方向と分散が大きい方向は一致するとは限らない')])+p('PCAで128次元を2次元へ落とすと、表示で失う情報があります。二次元で離れて見えることと、元の特徴空間での距離は区別します。クラスタのまとまりが、そのまま現実の正しい分類を意味するとも限りません。'))
 body+=refs([('scikit-learn：教師あり学習の公式ガイド','https://scikit-learn.org/stable/supervised_learning.html'),('scikit-learn：教師なし学習の公式ガイド','https://scikit-learn.org/stable/unsupervised_learning.html')])
 page('classics','補足 — 古典的な機械学習','研究例と補足','OPTIONAL / CLASSICAL METHODS','線形モデル、木、SVM、クラスタリング、PCA。主役の深層学習の周りにある方法を短く整理します。',body)
